(1009,'wpcode_snippets','a:1:{s:10:\"everywhere\";a:1:{i:0;a:14:{s:2:\"id\";i:255;s:5:\"title\";s:17:\"Parche SMTP Login\";s:4:\"code\";s:575:\"add_filter( \'wp_mail_smtp_custom_options\', function( $phpmailer ) {\r\n    // 1. Forzar confianza en el certificado SSL (Soluciona el error de certificado previo)\r\n    $phpmailer->SMTPOptions = array(\r\n        \'ssl\' => array(\r\n            \'verify_peer\'       => false,\r\n            \'verify_peer_name\'  => false,\r\n            \'allow_self_signed\' => true\r\n        )\r\n    );\r\n\r\n    // 2. Forzar método de autenticación LOGIN (Soluciona el error 535 actual)\r\n    // Esto evita que use CRAM-MD5 que suele fallar\r\n    $phpmailer->AuthType = \'LOGIN\';\r\n\r\n    return $phpmailer;\r\n} );\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-02-03 09:44:49\";}}}','auto'),
