(1113,225,'_elementor_data','[{\"id\":\"eb26ce6\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"db3817d\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\n    .zitadel-search-container {\\n        max-width: 1200px;\\n        margin: 30px auto;\\n        background: #1a4f8b;\\n        padding: 30px;\\n        border-radius: 12px;\\n        box-shadow: 0 10px 25px rgba(0,0,0,0.15);\\n        font-family: \'Segoe UI\', Roboto, sans-serif;\\n    }\\n\\n    .zitadel-search-title {\\n        color: #ffffff;\\n        margin-bottom: 20px;\\n        font-size: 18px;\\n        text-transform: uppercase;\\n        letter-spacing: 1px;\\n        font-weight: bold;\\n    }\\n\\n    .zitadel-search-flex {\\n        display: flex;\\n        gap: 15px;\\n        flex-wrap: wrap;\\n    }\\n\\n    .zitadel-search-flex input, \\n    .zitadel-search-flex select {\\n        flex: 1;\\n        min-width: 200px;\\n        padding: 12px;\\n        border: 1px solid #ffffff;\\n        border-radius: 6px;\\n        font-size: 14px;\\n        outline: none;\\n    }\\n\\n    .zitadel-btn-search {\\n        background: #2172bd;\\n        color: white;\\n        padding: 12px 40px;\\n        border: 2px solid #2172bd;\\n        border-radius: 6px;\\n        font-weight: bold;\\n        cursor: pointer;\\n        transition: 0.3s;\\n        text-transform: uppercase;\\n    }\\n\\n    .zitadel-btn-search:hover { \\n        background: #164a7d;\\n        border-color: #164a7d;\\n    }\\n\\n    \\/* GRID Y TARJETAS *\\/\\n    .zitadel-grid {\\n        display: grid;\\n        grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));\\n        gap: 30px;\\n        max-width: 1200px;\\n        margin: 40px auto;\\n        padding: 0 20px;\\n        font-family: \'Segoe UI\', sans-serif;\\n    }\\n\\n    .zitadel-card {\\n        background: #ffffff;\\n        border-radius: 10px;\\n        overflow: hidden;\\n        box-shadow: 0 5px 15px rgba(0,0,0,0.08);\\n        border: 1px solid #e1e8ed;\\n        display: flex;\\n        flex-direction: column;\\n        transition: opacity 0.4s ease, transform 0.4s ease; \\/* Transici\\u00f3n suave *\\/\\n    }\\n\\n    .zitadel-image {\\n        height: 230px;\\n        background-size: cover;\\n        background-position: center;\\n        position: relative;\\n    }\\n\\n    .zitadel-status {\\n        position: absolute;\\n        top: 15px;\\n        right: 15px;\\n        background: #1a4f8b;\\n        color: white;\\n        padding: 6px 15px;\\n        font-size: 12px;\\n        font-weight: bold;\\n        border-radius: 4px;\\n    }\\n\\n    .zitadel-info { padding: 25px; flex-grow: 1; }\\n    .zitadel-price { font-size: 24px; font-weight: 800; color: #1a4f8b; }\\n    .zitadel-location { font-size: 13px; color: #7f8c8d; text-transform: uppercase; font-weight: 600; margin-bottom: 10px;}\\n    .zitadel-title { font-size: 19px; color: #2c3e50; font-weight: 700; margin-bottom: 10px; min-height: 50px;}\\n    .zitadel-text { font-size: 14px; color: #57606f; line-height: 1.6; margin-bottom: 20px;}\\n\\n    .zitadel-specs {\\n        display: flex;\\n        justify-content: space-between;\\n        padding-top: 15px;\\n        border-top: 1px solid #f1f2f6;\\n        font-size: 13px;\\n        color: #2c3e50;\\n    }\\n\\n    #no-results {\\n        display: none;\\n        text-align: center;\\n        grid-column: 1 \\/ -1;\\n        padding: 50px;\\n        color: #7f8c8d;\\n        font-weight: bold;\\n    }\\n<\\/style>\\n\\n<div class=\\\"zitadel-search-container\\\">\\n    <div class=\\\"zitadel-search-title\\\">Buscador Inmobiliario<\\/div>\\n    <div class=\\\"zitadel-search-flex\\\">\\n        <input type=\\\"text\\\" id=\\\"filter-text\\\" placeholder=\\\"\\u00bfD\\u00f3nde quieres vivir? (Zona, Ciudad...)\\\">\\n        \\n        <select id=\\\"filter-type\\\">\\n            <option value=\\\"todos\\\">Cualquier tipo<\\/option>\\n            <option value=\\\"piso\\\">Pisos<\\/option>\\n            <option value=\\\"chalet\\\">Chalets<\\/option>\\n            <option value=\\\"estudio\\\">Estudios<\\/option>\\n        <\\/select>\\n\\n        <select id=\\\"filter-price\\\">\\n            <option value=\\\"9999999\\\">Sin l\\u00edmite de precio<\\/option>\\n            <option value=\\\"150000\\\">Hasta 150.000 \\u20ac<\\/option>\\n            <option value=\\\"300000\\\">Hasta 300.000 \\u20ac<\\/option>\\n            <option value=\\\"600000\\\">Hasta 600.000 \\u20ac<\\/option>\\n        <\\/select>\\n\\n        <button type=\\\"button\\\" class=\\\"zitadel-btn-search\\\" onclick=\\\"lanzarBusqueda()\\\">BUSCAR<\\/button>\\n    <\\/div>\\n<\\/div>\\n\\n<div class=\\\"zitadel-grid\\\" id=\\\"grid-inmuebles\\\">\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"chalet\\\" data-precio=\\\"585000\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1613490493576-7fde63acd811?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">VENTA<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">585.000 \\u20ac<\\/div>\\n            <div class=\\\"zitadel-location\\\">Cabo Estai, Canido<\\/div>\\n            <div class=\\\"zitadel-title\\\">Villa de Lujo con Vistas Panor\\u00e1micas<\\/div>\\n            <p class=\\\"zitadel-text\\\">Exclusiva propiedad con piscina de borde infinito y dom\\u00f3tica.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>5 Dorm.<\\/span><span>4 Ba\\u00f1os<\\/span><span>320 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"piso\\\" data-precio=\\\"310000\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1512917774080-9991f1c4c750?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">VENTA<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">310.000 \\u20ac<\\/div>\\n            <div class=\\\"zitadel-location\\\">Plaza Compostela, Centro<\\/div>\\n            <div class=\\\"zitadel-title\\\">\\u00c1tico Reformado Hist\\u00f3rico<\\/div>\\n            <p class=\\\"zitadel-text\\\">Vivienda de dise\\u00f1o con terraza privada de 20 metros.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>2 Dorm.<\\/span><span>2 Ba\\u00f1os<\\/span><span>95 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"chalet\\\" data-precio=\\\"1200\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1564013799919-ab600027ffc6?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">ALQUILER<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">1.200 \\u20ac\\/mes<\\/div>\\n            <div class=\\\"zitadel-location\\\">Teis, Vigo<\\/div>\\n            <div class=\\\"zitadel-title\\\">Chalet Unifamiliar con Jard\\u00edn<\\/div>\\n            <p class=\\\"zitadel-text\\\">Ideal familias. Amplia parcela y garaje doble.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>4 Dorm.<\\/span><span>3 Ba\\u00f1os<\\/span><span>180 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"piso\\\" data-precio=\\\"225000\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1560448204-e02f11c3d0e2?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">VENTA<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">225.000 \\u20ac<\\/div>\\n            <div class=\\\"zitadel-location\\\">Samil, Playa<\\/div>\\n            <div class=\\\"zitadel-title\\\">Apartamento Exterior Primera L\\u00ednea<\\/div>\\n            <p class=\\\"zitadel-text\\\">Vistas directas a las Islas C\\u00edes. Incluye garaje.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>2 Dorm.<\\/span><span>1 Ba\\u00f1o<\\/span><span>70 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"chalet\\\" data-precio=\\\"740000\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1600566753376-12c8ab7fb75b?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">VENTA<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">740.000 \\u20ac<\\/div>\\n            <div class=\\\"zitadel-location\\\">Bouzas, Casco Antiguo<\\/div>\\n            <div class=\\\"zitadel-title\\\">Casa Se\\u00f1orial de Piedra Rehabilitada<\\/div>\\n            <p class=\\\"zitadel-text\\\">Muros de canter\\u00eda y estilo industrial moderno.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>6 Dorm.<\\/span><span>4 Ba\\u00f1os<\\/span><span>450 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"zitadel-card\\\" data-tipo=\\\"estudio\\\" data-precio=\\\"950\\\">\\n        <div class=\\\"zitadel-image\\\" style=\\\"background-image: url(\'https:\\/\\/images.unsplash.com\\/photo-1493809842364-78817add7ffb?w=800\');\\\">\\n            <div class=\\\"zitadel-status\\\">ALQUILER<\\/div>\\n        <\\/div>\\n        <div class=\\\"zitadel-info\\\">\\n            <div class=\\\"zitadel-price\\\">950 \\u20ac\\/mes<\\/div>\\n            <div class=\\\"zitadel-location\\\">V\\u00eda Norte, Vialia<\\/div>\\n            <div class=\\\"zitadel-title\\\">Estudio Minimalista Obra Nueva<\\/div>\\n            <p class=\\\"zitadel-text\\\">M\\u00e1xima eficiencia energ\\u00e9tica junto a Vialia.<\\/p>\\n            <div class=\\\"zitadel-specs\\\">\\n                <span>1 Dorm.<\\/span><span>1 Ba\\u00f1o<\\/span><span>45 m\\u00b2<\\/span>\\n            <\\/div>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div id=\\\"no-results\\\">No se han encontrado resultados.<\\/div>\\n<\\/div>\\n\\n<script>\\nfunction lanzarBusqueda() {\\n    const valTexto = document.getElementById(\'filter-text\').value.toLowerCase();\\n    const valTipo = document.getElementById(\'filter-type\').value;\\n    const valPrecioMax = parseInt(document.getElementById(\'filter-price\').value);\\n    \\n    const tarjetas = document.getElementsByClassName(\'zitadel-card\');\\n    const aviso = document.getElementById(\'no-results\');\\n    let contador = 0;\\n\\n    for (let i = 0; i < tarjetas.length; i++) {\\n        const t = tarjetas[i];\\n        const matchTexto = t.innerText.toLowerCase().includes(valTexto);\\n        const matchTipo = (valTipo === \\\"todos\\\" || t.getAttribute(\'data-tipo\') === valTipo);\\n        const matchPrecio = (parseInt(t.getAttribute(\'data-precio\')) <= valPrecioMax);\\n\\n        if (matchTexto && matchTipo && matchPrecio) {\\n            t.style.display = \\\"flex\\\";\\n            t.style.opacity = \\\"1\\\";\\n            contador++;\\n        } else {\\n            t.style.display = \\\"none\\\";\\n            t.style.opacity = \\\"0\\\";\\n        }\\n    }\\n    aviso.style.display = (contador === 0) ? \\\"block\\\" : \\\"none\\\";\\n}\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),
