(2806,547,'_elementor_data','[{\"id\":\"cc2f30e\",\"elType\":\"container\",\"settings\":{\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"81f2e97\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!DOCTYPE html>\\r\\n<html lang=\\\"es\\\">\\r\\n<head>\\r\\n  <meta charset=\\\"UTF-8\\\" \\/>\\r\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\"\\/>\\r\\n  <title>Distribuci\\u00f3n de tareas | Zitadel Inmobiliaria<\\/title>\\r\\n  <style>\\r\\n    @import url(\'https:\\/\\/fonts.googleapis.com\\/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600&family=JetBrains+Mono:wght@400;500&display=swap\');\\r\\n\\r\\n    :root {\\r\\n      \\/* Iria \\u2014 morado *\\/\\r\\n      --morado:        #6c63cc;\\r\\n      --morado-claro:  #eeedfe;\\r\\n      --morado-acento: #3C3489;\\r\\n\\r\\n      \\/* Josean\\u00eda \\u2014 verde *\\/\\r\\n      --verde:         #2a9d6e;\\r\\n      --verde-claro:   #e1f5ee;\\r\\n      --verde-acento:  #085041;\\r\\n\\r\\n      \\/* Ambas \\u2014 naranja *\\/\\r\\n      --naranja:        #e07b2a;\\r\\n      --naranja-claro:  #fff3e8;\\r\\n      --naranja-acento: #7a3f00;\\r\\n\\r\\n      --gris-texto:  #2c2c2c;\\r\\n      --gris-suave:  #f5f5f3;\\r\\n      --gris-borde:  #e0e0dc;\\r\\n      --code-bg:     #1e2130;\\r\\n      --code-texto:  #a8d8a8;\\r\\n    }\\r\\n\\r\\n    * { box-sizing: border-box; margin: 0; padding: 0; }\\r\\n\\r\\n    body {\\r\\n      font-family: \'DM Sans\', sans-serif;\\r\\n      background: #fafaf8;\\r\\n      color: var(--gris-texto);\\r\\n      line-height: 1.75;\\r\\n      padding: 40px 20px 80px;\\r\\n    }\\r\\n\\r\\n    .contenedor {\\r\\n      max-width: 820px;\\r\\n      margin: 0 auto;\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 SECCI\\u00d3N GEN\\u00c9RICA \\u2500\\u2500 *\\/\\r\\n    .seccion {\\r\\n      margin-bottom: 52px;\\r\\n    }\\r\\n\\r\\n    .seccion > p {\\r\\n      font-size: 15px;\\r\\n      color: #3a3a3a;\\r\\n      margin-bottom: 28px;\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 BLOQUES DE INTEGRANTE \\u2500\\u2500 *\\/\\r\\n    .bloque-persona {\\r\\n      border-radius: 0 8px 8px 0;\\r\\n      padding: 22px 24px;\\r\\n      margin-bottom: 20px;\\r\\n    }\\r\\n    .bloque-persona.iria {\\r\\n      border-left: 5px solid var(--morado);\\r\\n      background: var(--morado-claro);\\r\\n    }\\r\\n    .bloque-persona.joseania {\\r\\n      border-left: 5px solid var(--verde);\\r\\n      background: var(--verde-claro);\\r\\n    }\\r\\n    .bloque-persona.ambas {\\r\\n      border-left: 5px solid var(--naranja);\\r\\n      background: var(--naranja-claro);\\r\\n    }\\r\\n\\r\\n    .bloque-persona h3 {\\r\\n      font-family: \'DM Serif Display\', serif;\\r\\n      font-size: 18px;\\r\\n      font-weight: 700;\\r\\n      margin-bottom: 4px;\\r\\n      color: #1a1a1a;\\r\\n    }\\r\\n    .bloque-persona .subtitulo {\\r\\n      font-size: 11px;\\r\\n      font-weight: 600;\\r\\n      letter-spacing: 1.5px;\\r\\n      text-transform: uppercase;\\r\\n      margin-bottom: 14px;\\r\\n      font-family: \'JetBrains Mono\', monospace;\\r\\n    }\\r\\n    .bloque-persona.iria     .subtitulo { color: var(--morado); }\\r\\n    .bloque-persona.joseania .subtitulo { color: var(--verde); }\\r\\n    .bloque-persona.ambas    .subtitulo { color: var(--naranja); }\\r\\n\\r\\n    .bloque-persona ul {\\r\\n      padding-left: 18px;\\r\\n    }\\r\\n    .bloque-persona ul li {\\r\\n      font-size: 14px;\\r\\n      color: #333;\\r\\n      margin-bottom: 6px;\\r\\n    }\\r\\n    .bloque-persona ul li:last-child { margin-bottom: 0; }\\r\\n\\r\\n    .cierre {\\r\\n      font-size: 15px;\\r\\n      color: #444;\\r\\n      margin-top: 8px;\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 T\\u00cdTULO DE SECCI\\u00d3N \\u2500\\u2500 *\\/\\r\\n    .titulo-seccion {\\r\\n      font-family: \'DM Serif Display\', serif;\\r\\n      font-size: 22px;\\r\\n      color: #1a1a1a;\\r\\n      margin-bottom: 6px;\\r\\n    }\\r\\n    .titulo-meta {\\r\\n      font-size: 12px;\\r\\n      color: #888;\\r\\n      font-family: \'JetBrains Mono\', monospace;\\r\\n      margin-bottom: 28px;\\r\\n      letter-spacing: 0.5px;\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 TABLA DE FASES \\u2500\\u2500 *\\/\\r\\n    .tabla-fases {\\r\\n      width: 100%;\\r\\n      border-collapse: collapse;\\r\\n      font-size: 13px;\\r\\n      margin-top: 4px;\\r\\n    }\\r\\n    .tabla-fases thead tr {\\r\\n      border-bottom: 2px solid #1a1a1a;\\r\\n    }\\r\\n    .tabla-fases th {\\r\\n      padding: 10px 12px;\\r\\n      text-align: left;\\r\\n      font-weight: 600;\\r\\n      color: #1a1a1a;\\r\\n      background: var(--gris-suave);\\r\\n      font-size: 12px;\\r\\n      letter-spacing: 0.3px;\\r\\n    }\\r\\n    .tabla-fases td {\\r\\n      padding: 10px 12px;\\r\\n      border-bottom: 1px solid var(--gris-borde);\\r\\n      color: #555;\\r\\n      vertical-align: middle;\\r\\n    }\\r\\n    .tabla-fases td:first-child {\\r\\n      color: #1a1a1a;\\r\\n      font-weight: 500;\\r\\n    }\\r\\n    .tabla-fases tr:nth-child(even) td {\\r\\n      background: #fafaf8;\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 BADGES DE RESPONSABLE \\u2500\\u2500 *\\/\\r\\n    .badge {\\r\\n      display: inline-block;\\r\\n      font-size: 11px;\\r\\n      font-weight: 600;\\r\\n      padding: 3px 10px;\\r\\n      border-radius: 20px;\\r\\n      font-family: \'DM Sans\', sans-serif;\\r\\n      white-space: nowrap;\\r\\n    }\\r\\n    .badge.iria {\\r\\n      background: var(--morado-claro);\\r\\n      color: var(--morado-acento);\\r\\n    }\\r\\n    .badge.joseania {\\r\\n      background: var(--verde-claro);\\r\\n      color: var(--verde-acento);\\r\\n    }\\r\\n    .badge.ambas {\\r\\n      background: var(--naranja-claro);\\r\\n      color: var(--naranja-acento);\\r\\n    }\\r\\n\\r\\n    \\/* \\u2500\\u2500 SEPARADOR \\u2500\\u2500 *\\/\\r\\n    hr {\\r\\n      border: none;\\r\\n      border-top: 1px solid var(--gris-borde);\\r\\n      margin: 48px 0;\\r\\n    }\\r\\n  <\\/style>\\r\\n<\\/head>\\r\\n<body>\\r\\n<div class=\\\"contenedor\\\">\\r\\n\\r\\n  <!-- DISTRIBUCI\\u00d3N DE TAREAS -->\\r\\n  <div class=\\\"seccion\\\">\\r\\n    <h2 class=\\\"titulo-seccion\\\">Distribuci\\u00f3n de tareas<\\/h2>\\r\\n    <p class=\\\"titulo-meta\\\">Roles por integrante<\\/p>\\r\\n\\r\\n    <p>La distribuci\\u00f3n de tareas del proyecto se ha definido teniendo en cuenta el perfil de cada integrante, aunque con coordinaci\\u00f3n continua en los puntos en los que las distintas partes se solapan.<\\/p>\\r\\n\\r\\n    <!-- IRIA -->\\r\\n    <div class=\\\"bloque-persona iria\\\">\\r\\n      <h3>Iria<\\/h3>\\r\\n      <p class=\\\"subtitulo\\\">Redes \\u00b7 Seguridad \\u00b7 Monitorizaci\\u00f3n<\\/p>\\r\\n      <ul>\\r\\n        <li>Configuraci\\u00f3n de Proxmox VE y virtualizaci\\u00f3n<\\/li>\\r\\n        <li>Configuraci\\u00f3n del firewall con OPNsense (reglas y segmentaci\\u00f3n)<\\/li>\\r\\n        <li>Dise\\u00f1o y configuraci\\u00f3n de VLANs y arquitectura de red<\\/li>\\r\\n        <li>Acceso remoto seguro con Tailscale<\\/li>\\r\\n        <li>Sistema de detecci\\u00f3n de intrusiones con CrowdSec<\\/li>\\r\\n        <li>Configuraci\\u00f3n de Traefik como proxy inverso<\\/li>\\r\\n        <li>Gesti\\u00f3n de certificados SSL con Let\'s Encrypt<\\/li>\\r\\n        <li>Estrategia de copias de seguridad 3-2-1<\\/li>\\r\\n        <li>Configuraci\\u00f3n de Zabbix (m\\u00e9tricas y alertas)<\\/li>\\r\\n        <li>Desarrollo del frontend en WordPress (tema, contenidos y ajustes)<\\/li>\\r\\n      <\\/ul>\\r\\n    <\\/div>\\r\\n\\r\\n    <!-- JOSEAN\\u00cdA -->\\r\\n    <div class=\\\"bloque-persona joseania\\\">\\r\\n      <h3>Josean\\u00eda<\\/h3>\\r\\n      <p class=\\\"subtitulo\\\">Automatizaci\\u00f3n \\u00b7 Infraestructura \\u00b7 Backend<\\/p>\\r\\n      <ul>\\r\\n        <li>Despliegue de VMs con Terraform<\\/li>\\r\\n        <li>Gesti\\u00f3n de credenciales con Teampass<\\/li>\\r\\n        <li>Dise\\u00f1o e implementaci\\u00f3n de la base de datos con MariaDB<\\/li>\\r\\n        <li>Despliegue del stack con Docker Compose<\\/li>\\r\\n        <li>Scripts de automatizaci\\u00f3n en Bash<\\/li>\\r\\n        <li>Instalaci\\u00f3n y configuraci\\u00f3n de agentes Zabbix en las VMs<\\/li>\\r\\n        <li>Definici\\u00f3n de dashboards y triggers de alertas en Zabbix<\\/li>\\r\\n        <li>Configuraci\\u00f3n de Samba con integraci\\u00f3n LDAP para gesti\\u00f3n centralizada de usuarios y recursos compartidos<\\/li>\\r\\n        <li>Backend de WordPress: configuraci\\u00f3n de la base de datos, variables de entorno y conexi\\u00f3n con el contenedor<\\/li>\\r\\n        <li>Gesti\\u00f3n del repositorio y control de versiones del proyecto<\\/li>\\r\\n      <\\/ul>\\r\\n    <\\/div>\\r\\n\\r\\n    <!-- AMBAS -->\\r\\n    <div class=\\\"bloque-persona ambas\\\">\\r\\n      <h3>Trabajo conjunto<\\/h3>\\r\\n      <p class=\\\"subtitulo\\\">Coordinaci\\u00f3n \\u00b7 Entrega<\\/p>\\r\\n      <ul>\\r\\n        <li>Planificaci\\u00f3n general del proyecto y arquitectura inicial<\\/li>\\r\\n        <li>Desarrollo de playbooks de Ansible<\\/li>\\r\\n        <li>Pruebas de integraci\\u00f3n entre sistemas<\\/li>\\r\\n        <li>Documentaci\\u00f3n final (memoria y blog)<\\/li>\\r\\n      <\\/ul>\\r\\n    <\\/div>\\r\\n\\r\\n    <p class=\\\"cierre\\\">De esta forma, aunque cada una tiene un \\u00e1rea principal bien definida, el proyecto se est\\u00e1 desarrollando de manera coordinada para asegurar que todas las piezas encajen correctamente.<\\/p>\\r\\n  <\\/div>\\r\\n\\r\\n\\r\\n  <hr>\\r\\n\\r\\n\\r\\n  <!-- FASES DEL PROYECTO -->\\r\\n  <div class=\\\"seccion\\\">\\r\\n    <h2 class=\\\"titulo-seccion\\\">Fases del proyecto<\\/h2>\\r\\n    <p class=\\\"titulo-meta\\\">Planificaci\\u00f3n temporal \\u00b7 12 fases<\\/p>\\r\\n\\r\\n    <table class=\\\"tabla-fases\\\">\\r\\n      <thead>\\r\\n        <tr>\\r\\n          <th>Fase<\\/th>\\r\\n          <th>Fechas<\\/th>\\r\\n          <th>Duraci\\u00f3n<\\/th>\\r\\n          <th>Responsable<\\/th>\\r\\n          <th>Descripci\\u00f3n<\\/th>\\r\\n        <\\/tr>\\r\\n      <\\/thead>\\r\\n      <tbody>\\r\\n        <tr>\\r\\n          <td>1. Planificaci\\u00f3n y an\\u00e1lisis<\\/td>\\r\\n          <td>02 mar \\u2013 10 mar<\\/td>\\r\\n          <td>1 semana<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Definici\\u00f3n de objetivos y arquitectura inicial<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td rowspan=\\\"2\\\">2. Dise\\u00f1o de arquitectura<\\/td>\\r\\n          <td>11 mar \\u2013 20 mar<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge iria\\\">Iria<\\/span><\\/td>\\r\\n          <td>Dise\\u00f1o de red<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>11 mar \\u2013 20 mar<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge joseania\\\">Josean\\u00eda<\\/span><\\/td>\\r\\n          <td>Dise\\u00f1o de infraestructura<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>3. Hardware y virtualizaci\\u00f3n<\\/td>\\r\\n          <td>21 mar \\u2013 30 mar<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge iria\\\">Iria<\\/span><\\/td>\\r\\n          <td>Instalaci\\u00f3n de Proxmox<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>4. Red, conectividad y servicios base<\\/td>\\r\\n          <td>25 mar \\u2013 10 abr<\\/td>\\r\\n          <td>2 semanas<\\/td>\\r\\n          <td><span class=\\\"badge iria\\\">Iria<\\/span><\\/td>\\r\\n          <td>Firewall, VLANs y segmentaci\\u00f3n de red<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>5. Base de datos<\\/td>\\r\\n          <td>08 abr \\u2013 15 abr<\\/td>\\r\\n          <td>1 semana<\\/td>\\r\\n          <td><span class=\\\"badge joseania\\\">Josean\\u00eda<\\/span><\\/td>\\r\\n          <td>MariaDB<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>6. Despliegue web<\\/td>\\r\\n          <td>12 abr \\u2013 22 abr<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>WordPress y Docker<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>7. Automatizaci\\u00f3n<\\/td>\\r\\n          <td>15 abr \\u2013 30 abr<\\/td>\\r\\n          <td>2 semanas<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Terraform y Ansible<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>8. Seguridad<\\/td>\\r\\n          <td>20 abr \\u2013 05 may<\\/td>\\r\\n          <td>2 semanas<\\/td>\\r\\n          <td><span class=\\\"badge iria\\\">Iria<\\/span><\\/td>\\r\\n          <td>Seguridad completa<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>9. Monitorizaci\\u00f3n<\\/td>\\r\\n          <td>01 may \\u2013 10 may<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Zabbix<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>10. Pruebas<\\/td>\\r\\n          <td>10 may \\u2013 20 may<\\/td>\\r\\n          <td>1,5 semanas<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Testing<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>11. Documentaci\\u00f3n<\\/td>\\r\\n          <td>02 mar \\u2013 02 jun<\\/td>\\r\\n          <td>3 meses (ongoing)<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Memoria y blog<\\/td>\\r\\n        <\\/tr>\\r\\n        <tr>\\r\\n          <td>12. Entrega final<\\/td>\\r\\n          <td>03 jun \\u2013 05 jun<\\/td>\\r\\n          <td>3 d\\u00edas<\\/td>\\r\\n          <td><span class=\\\"badge ambas\\\">Ambas<\\/span><\\/td>\\r\\n          <td>Entrega<\\/td>\\r\\n        <\\/tr>\\r\\n      <\\/tbody>\\r\\n    <\\/table>\\r\\n  <\\/div>\\r\\n\\r\\n<\\/div>\\r\\n<\\/body>\\r\\n<\\/html>\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"d07336b\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"c6f7b6a\",\"elType\":\"widget\",\"settings\":{\"space\":{\"unit\":\"px\",\"size\":23,\"sizes\":[]},\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[],\"widgetType\":\"spacer\"}],\"isInner\":false},{\"id\":\"d218e96\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"0f41069\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"https:\\/\\/zitadel.a24iriabc.iesteis.gal\\/wp-content\\/uploads\\/2026\\/04\\/1777028198327-864f82e2-f684-49e5-b757-55c13b040516_1.png\",\"id\":524,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":false},{\"id\":\"c1799b9\",\"elType\":\"container\",\"settings\":{\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[{\"id\":\"08278f3\",\"elType\":\"widget\",\"settings\":{\"text\":\"Separador\",\"eael_image_masking_custom_clip_path\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\",\"eael_image_masking_custom_clip_path_hover\":\"clip-path: polygon(50% 0%, 80% 10%, 100% 35%, 100% 70%, 80% 90%, 50% 100%, 20% 90%, 0% 70%, 0% 35%, 20% 10%);\"},\"elements\":[],\"widgetType\":\"divider\"}],\"isInner\":false}]'),
