ding: 25px;\n        border-left: 4px solid var(--zt-azul);\n        border-radius: 8px;\n        margin-top: 30px;\n    }\n    /* Estilos del Formulario */\n    .form-group {\n        margin-bottom: 20px;\n    }\n    .form-group label {\n        display: block;\n        margin-bottom: 8px;\n        font-weight: 600;\n        font-size: 14px;\n        color: var(--zt-oscuro);\n    }\n    .form-row {\n        display: flex;\n        gap: 20px;\n    }\n    .form-row .form-group {\n        flex: 1;\n    }\n    .zitadel-input {\n        width: 100%;\n        padding: 12px 15px;\n        border: 1px solid var(--zt-borde);\n        border-radius: 8px;\n        font-size: 14px;\n        font-family: inherit;\n        color: var(--zt-texto);\n        box-sizing: border-box;\n        transition: all 0.3s ease;\n        background-color: #fff;\n    }\n    .zitadel-input:focus {\n        border-color: var(--zt-azul);\n        outline: none;\n        box-shadow: 0 0 0 3px rgba(32, 97, 164, 0.1);\n    }\n    /* BOTÓN IDÉNTICO AL BLOG */\n    .zitadel-btn {\n        background-color: var(--zt-azul);\n        color: white;\n        padding: 14px;\n        border: none;\n        border-radius: 6px; /* Sincronizado con botones del blog */\n        width: 100%;\n        font-size: 13px;\n        font-weight: 600;\n        cursor: pointer;\n        transition: background 0.3s ease;\n        text-transform: uppercase;\n        letter-spacing: 0.5px;\n        margin-top: 10px;\n    }\n    .zitadel-btn:hover {\n        background-color: var(--zt-oscuro);\n    }\n    /* Ajustes para móviles */\n    @media (max-width: 768px) {\n        .form-row {\n            flex-direction: column;\n            gap: 0;\n        }\n        .zitadel-contact-wrapper {\n            margin: 20px auto;\n        }\n        .zitadel-contact-col {\n            padding: 30px;\n        }\n    }\n</style>\n        <h2>Contacto</h2>\n        <p>\n            En <b>Zitadel Inmobiliaria</b> estamos listos para asesorar