(255,1,'2026-02-03 09:44:49','2026-02-03 08:44:49','add_filter( \'wp_mail_smtp_custom_options\', function( $phpmailer ) {\r\n    // 1. Forzar confianza en el certificado SSL (Soluciona el error de certificado previo)\r\n    $phpmailer->SMTPOptions = array(\r\n        \'ssl\' => array(\r\n            \'verify_peer\'       => false,\r\n            \'verify_peer_name\'  => false,\r\n            \'allow_self_signed\' => true\r\n        )\r\n    );\r\n\r\n    // 2. Forzar método de autenticación LOGIN (Soluciona el error 535 actual)\r\n    // Esto evita que use CRAM-MD5 que suele fallar\r\n    $phpmailer->AuthType = \'LOGIN\';\r\n\r\n    return $phpmailer;\r\n} );','Parche SMTP Login','','publish','closed','closed','','parche-smtp-login','','','2026-02-03 09:44:49','2026-02-03 08:44:49','',0,'https://zitadel.a24iriabc.iesteis.gal/wpcode/parche-smtp-login/',0,'wpcode','',0),
