: collapse; width: 100%;\">\n    <thead style=\"background-color: #f2f2f2;\">\n      <tr>\n        <th>Fase</th>\n        <th>Fechas</th>\n        <th>Duración</th>\n        <th>Responsable(s)</th>\n        <th>Descripción</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>1. Planificación y análisis</td>\n        <td>02 mar – 10 mar</td>\n        <td>1 semana</td>\n        <td>Iria + Joseania</td>\n        <td>Definición de objetivos y arquitectura inicial</td>\n      </tr>\n      <tr>\n        <td rowspan=\"2\">2. Diseño de arquitectura</td>\n        <td>11 mar – 20 mar</td>\n        <td>1,5 semanas</td>\n        <td>Iria</td>\n        <td>Diseño de red</td>\n      </tr>\n      <tr>\n        <td>11 mar – 20 mar</td>\n        <td>1,5 semanas</td>\n        <td>Joseania</td>\n        <td>Diseño de infraestructura</td>\n      </tr>\n      <tr>\n        <td>3. Hardware y virtualización</td>\n        <td>21 mar – 30 mar</td>\n        <td>1,5 semanas</td>\n        <td>Iria</td>\n        <td>Instalación de Proxmox</td>\n      </tr>\n      <tr>\n        <td>4. Red, conectividad y servicios base</td>\n        <td>25 mar – 10 abr</td>\n        <td>2 semanas</td>\n        <td>Iria</td>\n        <td>Firewall, VLANs y DNS</td>\n      </tr>\n      <tr>\n        <td>5. Base de datos</td>\n        <td>08 abr – 15 abr</td>\n        <td>1 semana</td>\n        <td>Joseania</td>\n        <td>MariaDB</td>\n      </tr>\n      <tr>\n        <td>6. Despliegue web</td>\n        <td>12 abr – 22 abr</td>\n        <td>1,5 semanas</td>\n        <td>Iria + Joseanía</td>\n        <td>WordPress y Docker</td>\n      </tr>\n      <tr>\n        <td>7. Automatización</td>\n        <td>15 abr – 30 abr</td>\n        <td>2 semanas</td>\n        <td>Joseanía</td>\n        <td>Terraform y Ansible</td>\n      </tr>\n      <tr>\n        <td>8. Seguridad</td>\n        <td>20 abr – 05 may</td>\n        <td>2 semanas</td>\n        <td>Iria</td>\n        <td>Seguridad completa</td>\n      </tr>\n      <tr>\n        <td>9. Monitorización</td>\n        <td>01 may – 10 may</td>\n        <td>1,5 semanas</td>\n        <td>Joseanía</td>\n        <td>Zabbix</td>\n      </tr>\n      <tr>\n        <td>10. Pruebas</td>\n        <td>10 may – 20 may</td>\n        <td>1,5 semanas</td>\n        <td>Ambas</td>\n        <td>Testing</td>\n      </tr>\n      <tr>\n        <td>11. Documentación</td>\n        <td>02 mar – 02 jun</td>\n        <td>3 meses (Ongoing)</td>\n        <td>Ambas</td>\n        <td>Memoria y blog</td>\n      </tr>\n      <tr>\n        <td>12. Listo para entrega final</td>\n        <td>03 jun – 05 jun</td>\n        <td>3 días</td>\n        <td>Ambas</td>\n        <td>Entrega</td>\n      </tr>\n    </tbody>\n  </table>','Elementor #464','','inherit','closed','closed','','464-autosave-v1','','','2026-04-23 09:48:17','2026-04-23 07:48:17','',464,'https://zitadel.a24iriabc.iesteis.gal/?p=469',0,'revision','',0),
