r>\n      <tr>\n        <td>9. Monitorización</td>\n        <td>01 may – 10 may</td>\n        <td>1,5 semanas</td>\n        <td>Joseanía</td>\n        <td>Zabbix</td>\n      </tr>\n      <tr>\n        <td>10. Pruebas</td>\n        <td>10 may – 20 may</td>\n        <td>1,5 semanas</td>\n        <td>Ambas</td>\n        <td>Testing</td>\n      </tr>\n      <tr>\n        <td>11. Documentación</td>\n        <td>02 mar – 02 jun</td>\n        <td>3 meses (Ongoing)</td>\n        <td>Ambas</td>\n        <td>Memoria y blog</td>\n      </tr>\n      <tr>\n        <td>12. Listo para entrega final</td>\n        <td>03 jun – 05 jun</td>\n        <td>3 días</td>\n        <td>Ambas</td>\n        <td>Entrega</td>\n      </tr>\n    </tbody>\n  </table>','Elementor #473','','inherit','closed','closed','','473-revision-v1','','','2026-04-23 09:57:14','2026-04-23 07:57:14','',473,'https://zitadel.a24iriabc.iesteis.gal/?p=477',0,'revision','',0),
